//! Single-pass access-log aggregator that allocates only in `Aggregator::new()`.
//!
//! Do not edit this file, `baseline.rs` or `datagen.rs`. Implement `aggregator.rs`.
//!
//! # Line format
//!
//! `<unix_ms> <client_ip_v4> <METHOD> <path> <status> <bytes> <latency_us>`
//!
//! Fields are separated by exactly one space (0x20). A line ends at `\n`; the
//! last line may lack it. A line is *valid* when all of these hold, otherwise it
//! is *malformed*:
//!
//! * exactly 7 fields, none empty;
//! * `unix_ms`, `bytes`, `latency_us`: ASCII digits only (no sign, no `+`),
//!   value fits in `u64`. Leading zeros are allowed;
//! * `client_ip_v4`: four decimal octets separated by `.`. Each octet is 1 to 3
//!   ASCII digits, at most 255, and has no leading zero unless it is exactly `0`;
//! * `METHOD`: one or more ASCII letters `A`-`Z`;
//! * `path`: starts with `/`;
//! * `status`: exactly 3 ASCII digits, value 100 to 599.
//!
//! An empty line is malformed. A line whose content (excluding `\n`) is longer
//! than [`CARRY_CAP`] bytes is malformed. `\r` is an ordinary byte.

pub mod aggregator;
pub mod baseline;
pub mod datagen;

pub use aggregator::Aggregator;

/// Maximum line content length in bytes, and the size of the carry buffer.
pub const CARRY_CAP: usize = 4096;

/// Number of slots in the client table (`u32` each).
pub const TABLE_SLOTS: usize = 1 << 20;

/// Most distinct non-zero client addresses the table stores: `TABLE_SLOTS * 9 / 10`.
pub const MAX_STORED_CLIENTS: usize = TABLE_SLOTS * 9 / 10;

/// Number of latency histogram buckets.
pub const HIST_BUCKETS: usize = 32;

/// The slowest valid request seen.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SlowRequest {
    pub latency_us: u64,
    /// Byte offset, from the start of the whole input stream, of the first byte
    /// of the line. With several lines at the maximum latency, the lowest offset.
    pub line_offset: usize,
}

/// Aggregate over all valid lines of a stream.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Summary {
    /// Valid lines.
    pub lines: u64,
    /// Malformed lines. `lines + malformed` is the number of lines in the input.
    pub malformed: u64,
    /// Valid lines per status class. Index 0 is 1xx, index 4 is 5xx.
    pub by_status_class: [u64; 5],
    /// Sum of `bytes` over valid lines. Saturates at `u64::MAX`.
    pub total_bytes: u64,
    /// Bucket `i` counts valid lines with `floor(log2(latency_us + 1)) == i`,
    /// with the index clamped to 31. `latency_us + 1` saturates at `u64::MAX`.
    pub latency_hist: [u64; HIST_BUCKETS],
    /// Distinct client addresses stored: non-zero addresses held in the table
    /// plus one if `0.0.0.0` was seen. Exact until the table is full.
    pub distinct_clients_estimate: u64,
    /// Valid lines whose client address was neither in the table nor storable
    /// because the table already held `MAX_STORED_CLIENTS` addresses.
    pub clients_overflow: u64,
    /// `None` when there are no valid lines.
    pub slowest: Option<SlowRequest>,
}
